#include "CASIO_GUI/casio.hpp"

int main()
{
    casio::GUI gui;

    gui.setThemePreset(
        {{theme}}
    );

    auto* button =
        new casio::Button(
            {{position}}
        );

    gui.addItem(button);

    gui.runGUI();
    return 0;
}

auto* {{name}} =
    new casio::TextBox(
        {{position}},
        "",
        "{{placeholder}}",
        {{maxLength}},
        0,
        casio::TextBoxInputMode::MIXED
    );

{{name}}->setAutoAlphaOnFocus(true);

// ALPHA: text <-> numeric
// SHIFT: lowercase <-> Caps Lock in text mode
gui.addItem({{name}});

auto* {{scroll}} =
    new casio::ScrollView(
        {{position}},
        casio::LayoutMode::VERTICAL,
        {{padding}},
        {{gap}},
        true
    );

{{scroll}}->setScrollStep({{step}});
{{scroll}}->addChild({{child}}, {0, 0, {{childWidth}}, {{childHeight}}});

gui.addItem({{scroll}});

casio::ConfigFile {{config}};

{{config}}.setString(
    "{{section}}",
    "{{key}}",
    {{value}}
);

if(!{{config}}.saveSafe("{{file}}"))
{
    // Handle save error.
}

casio::ConfigFile loaded;

if(loaded.loadSafe("{{file}}"))
{
    std::string restored =
        loaded.getStringOr(
            "{{section}}",
            "{{key}}",
            ""
        );
}

gui.enableScreenshotCapture(
    {{key}},
    "{{defaultName}}"
);

gui.setScreenshotResultCallback(
    [](
        bool success,
        const std::string& path)
    {
        if(success)
        {
            // Saved under /Capt.
        }
    }
);

{{wheel}}->setOnChanged(
    [{{numeric}}, {{led}}](
        float hue,
        casio::Color color)
    {
        int hueInt =
            static_cast<int>(hue + 0.5f);

        {{numeric}}->setValue(hueInt);
        {{led}}->setOnColor(color);
        {{led}}->setState(casio::LEDState::ON);
    }
);

{{numeric}}->setOnChanged(
    [{{wheel}}](int hue)
    {
        {{wheel}}->setHue(
            static_cast<float>(hue)
        );
    }
);

auto* {{menu}} =
    new casio::MenuBar(
        {{position}},
        {"File", "Edit", "View"},
        0
    );

{{menu}}->setCallback(0, []() { /* File */ });
{{menu}}->setCallback(1, []() { /* Edit */ });
{{menu}}->setCallback(2, []() { /* View */ });

gui.addItem({{menu}});

auto* {{popup}} =
    new casio::PromptPopup(
        "{{title}}",
        "{{message}}",
        "{{defaultValue}}",
        {{maxLength}}
    );

{{popup}}->setOnSubmit(
    [](const std::string& value)
    {
        (void)value;
    }
);

{{popup}}->setGlobalPage();
gui.addItem({{popup}});
{{popup}}->open();

extern "C" bopti_image_t {{symbol}};

auto* {{name}} =
    new casio::ImageItem(
        {{position}},
        &{{symbol}}
    );

{{name}}->setUseThemeBorder(true);
gui.addItem({{name}});

casio::Checkbox {{child}}(
    {{childPosition}},
    "{{label}}",
    false
);

casio::Panel {{panel}}(
    {{panelPosition}},
    casio::LayoutMode::VERTICAL
);

// Child is non-owning and must outlive the Panel usage.
{{panel}}.addChild(
    &{{child}},
    {0, 0, {{childWidth}}, {{childHeight}}}
);

// Frozen v1 contract:
// EXIT closes/back/defocuses widgets.
// MENU remains an OS/application-switch key.
// Do not terminate the GUI loop on KEY_EXIT or KEY_MENU.
gui.runGUI();
